    98→        }
    99→
   100→        .project-name {
   101→            font-size: 13px;
   102→            font-weight: 500;
   103→            color: #f0f6fc;
   104→            display: flex;
   105→            align-items: center;
   106→            justify-content: space-between;
   107→        }
   108→
   109→        .session-name {
   110→            font-size: 13px;
   111→            color: #c9d1d9;
   112→            line-height: 1.4;
   113→            overflow: hidden;
   114→            text-overflow: ellipsis;
   115→            white-space: nowrap;
   116→        }
   117→
   118→        .session-meta {
