   122→        }
   123→
   124→        .count-badge {
   125→            background: #30363d;
   126→            color: #8b949e;
   127→            font-size: 11px;
   128→            padding: 2px 8px;
   129→            border-radius: 10px;
   130→        }
   131→
   132→        .back-btn {
   133→            padding: 10px 16px;
   134→            background: #21262d;
   135→            cursor: pointer;
   136→            font-size: 13px;
   137→            color: #58a6ff;
   138→            border-bottom: 1px solid #30363d;
   139→        }
   140→
   141→        .back-btn:hover {
   142→            background: #30363d;
   143→        }
   144→
   145→        /* Main content */
   146→        .main-content {
   147→            flex: 1;
   148→            display: flex;
   149→            flex-direction: column;
   150→            overflow: hidden;
   151→            background: #0d1117;
   152→        }
   153→
   154→        .conversation-header {
   155→            padding: 16px 24px;
   156→            background: #161b22;
   157→            border-bottom: 1px solid #30363d;
   158→            display: flex;
   159→            justify-content: space-between;
   160→            align-items: center;
   161→        }
   162→
   163→        .conversation-header h2 {
   164→            font-size: 15px;
   165→            font-weight: 600;
   166→            color: #f0f6fc;
