   174→
   175→        /* Filter controls */
   176→        .filter-controls {
   177→            display: flex;
   178→            gap: 12px;
   179→            align-items: center;
   180→        }
   181→
   182→        .filter-controls label {
   183→            font-size: 12px;
   184→            display: flex;
   185→            align-items: center;
   186→            gap: 4px;
   187→            cursor: pointer;
   188→            color: #8b949e;
