// Find mcp__puppeteer__puppeteer_navigate tool and scroll to it
const h = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'mcp__puppeteer__puppeteer_navigate');
if (h) h.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

// Find mcp__puppeteer__puppeteer_click tool
const h = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'mcp__puppeteer__puppeteer_click');
if (h) h.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

// Find mcp__puppeteer__puppeteer_click tool
const clickTool = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'mcp__puppeteer__puppeteer_click');
if (clickTool) clickTool.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

const evalTool = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'mcp__puppeteer__puppeteer_evaluate');
if (evalTool) evalTool.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

// Find Write tool
const writeTool = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'Write');
if (writeTool) writeTool.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

const editTool = Array.from(document.querySelectorAll('.tool-header')).find(el => el.textContent === 'Edit');
if (editTool) editTool.scrollIntoView({ behavior: 'instant', block: 'center' });
true;

// Get all tool headers and their parent message UUIDs
const results = [];
document.querySelectorAll('.tool-use').forEach(toolUse => {
  const toolName = toolUse.querySelector('.tool-header')?.textContent;
  const message = toolUse.closest('.message');
  const uuid = message?.dataset?.uuid;
  if (toolName && uuid && !results.find(r => r.tool === toolName)) {
    results.push({ tool: toolName, uuid: uuid });
  }
});
JSON.stringify(results, null, 2);

